import numpy as np
from scipy.interpolate import interp1d

def resample_profile(depths, temps, step=0.5):
    """Regrid a temperature profile onto a uniform depth grid."""
    grid = np.arange(depths[0], depths[-1] + step, step)
    f = interp1d(depths, temps, kind="cubic")
    return grid, f(grid)

def gradient(depths, temps):
    grid, values = resample_profile(depths, temps)
    return np.gradient(values, grid)

